    """
    This function uses the Shunting Yard algorithm to convert the infix expression
    to postfix notation and then evaluates the postfix expression to handle operator 
    precedence and parentheses correctly.
    """

    def precedence(op):
        if op in ('+', '-'):
            return 1
        if op in ('*', '/'):
            return 2
        return 0

    def apply_operator(operators, values):
        right = values.pop()
        left = values.pop()
        op = operators.pop()
        if op == '+':
            values.append(left + right)
        elif op == '-':
            values.append(left - right)
        elif op == '*':
            values.append(left * right)
        elif op == '/':
            values.append(left / right)

    def evaluate_postfix(expression):
