def evaluate(expr: str) -> float:
    """
    Evaluates a mathematical expression using the Shunting Yard algorithm 
    for converting infix notation to postfix notation and then evaluating 
    the postfix expression. Supports +, -, *, /, parentheses, and floating-point numbers.
    """

    def shunting_yard(expression):
        precedence = {'+': 1, '-': 1, '*': 2, '/': 2}
        output = []
        operators = []
        tokens = []

        # Tokenize the expression
        num = ''
        for char in expression:
            if char.isdigit() or char == '.':
                num += char
            else:
                if num:
                    tokens.append(num)
                    num = ''
                if char in precedence or char in '()':
                    tokens.append(char)
        if num:
            tokens.append(num)

        for token in tokens:
            if token.isnumeric() or '.' in token:
                output.append(float(token))
            elif token in precedence:
                while (operators and operators[-1] != '(' and
                       precedence[operators[-1]] >= precedence[token]):
                    output.append(operators.pop())
                operators.append(token)
            elif token == '(':
                operators.append(token)
            elif token == ')':
                while operators and operators[-1] != '(':
                    output.append(operators.pop())
                operators.pop()  # Remove the '('

        while operators:
            output.append(operators.pop())

        return output

    def evaluate_postfix(postfix):
        stack = []
        for token in postfix:
            if isinstance(token, float):
                stack.append(token)
            else:
                b = stack.pop()
                a = stack.pop()
                if token == '+':
                    stack.append(a + b)
                elif token == '-':
                    stack.append(a - b)
                elif token == '*':
                    stack.append(a * b)
                elif token == '/':
                    stack.append(a / b)
        return stack[0]

    postfix = shunting_yard(expr)
    return evaluate_postfix(postfix)
